    (* [comment removed for export] *)
    Ltac disj LV := try (destruct LV as [LV|LV]; [| disj LV]).
    Ltac leaf_open P1 :=
      let pc1 := fresh "pc1" in let LV := fresh "LV" in
      destruct P1 as (pc1 & ?r1 & ?m1 & ?E1 & LV); disj LV; splits LV; subst pc1; leaf_regs r1.
    Ltac creg1 := first [ eassumption | reflexivity | exact SPW96 | etransitivity; [eassumption| first [exact SPW96 | eassumption | reflexivity]] ].
    Ltac cregs_tac := unfold cregs; repeat (split; [creg1|]); creg1.
    (* [comment removed for export] *)
    Ltac nsx NS ST INB SHB :=
      first [ match goal with Hm : munch ?W ?mc ?m1, Hw : wmono _ ?mc ?m1, Hi : mem_inv _ ?m1 |- _ =>
                let SUB := fresh "SUB" in
                assert (SUB : sub_fp W [(bv_unsigned sp - 96, bv_unsigned sp)]%Z) by (first [apply sub_96; lia | apply sub_nil]);
                pose proof (nst_frame mc m1 W NS Hm (sub_lo W SUB) Hw Hi) as NSx; pose proof (stk_frame mc m1 W ST Hm SUB Hw) as STx;
                pose proof (pinb_frame mc m1 W INB Hm (sub_lo W SUB)) as INBx; pose proof (pshb_frame mc m1 W SHB Hm (sub_lo W SUB)) as SHBx
              end
            | pose proof NS as NSx; pose proof ST as STx; pose proof INB as INBx; pose proof SHB as SHBx ].
    Ltac mp_tac := first [ eassumption | eapply (ah_mpres_trans H RT); [eassumption| eassumption] ].


