    (* [comment removed for export] *)
    Lemma fin_fin : forall msF mo mc (r : rv) Fx j8 (mw : word) (bc xc xn : Z) j6 slv (p' : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x103754) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) ->
      nframe mc spw j8 mw (Z_to_bv 64 bc) (Z_to_bv 64 xc) (b8 xn) (b8 1) j6 slv s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 p' -> p < p' <= e -> -2^31 < bc < 2^31 -> 0 <= xc < 2^31 -> 0 <= xn <= 1 ->
      as_SR H POST (mkCfg msF mo).
Proof.
