    Ltac norm_swrap :=
      try (repeat match goal with Hs : context [sx32 (Z_to_bv 64 ?b)] |- _ => rewrite (sx32_ssmall b) in Hs by lia end);
      try (repeat match goal with Hs : context [Z_to_bv 64 (0 + - bv_unsigned (Z_to_bv 64 ?b))] |- _ => rewrite (neg_u64_bv b) in Hs end);
      try (repeat match goal with Hs : context [bv_swrap 32 (0 - bv_unsigned (Z_to_bv 64 ?b))] |- _ => rewrite (neg_u64_swrap32 b) in Hs by lia end);
      try (repeat match goal with Hs : context [bv_swrap 32 (bv_unsigned (Z_to_bv 64 ?b))] |- _ => rewrite (swrap32_of_u64_0 b) in Hs by lia end);
      try (repeat match goal with Hs : context [bv_swrap 32 (bv_unsigned (Z_to_bv 64 ?b) + ?k)] |- _ =>
             let kk := eval vm_compute in (k mod 2^32)%Z in
             let E := fresh "SW" in
             first [ assert (E : bv_swrap 32 (bv_unsigned (Z_to_bv 64 b) + k) = b + kk) by (apply (swrap32_of_u64_mod b k kk); [reflexivity| lia])
                   | assert (E : bv_swrap 32 (bv_unsigned (Z_to_bv 64 b) + k) = b + (kk - 4294967296)) by (apply (swrap32_of_u64_mod2 b k kk); [reflexivity| lia]) ];
             rewrite E in Hs; clear E end);
      try (repeat match goal with Hs : context [bv_swrap 32 ?z] |- _ => rewrite (swrap32_id z) in Hs by lia end).
