    Lemma frh_loop_n : forall (n : nat) (q : Z) msF mo mc (r : rv) Fx (j8 : list byte) (mw : word) (bc : Z) (j6 : list byte) (slv : word),
      (Z.to_nat (e - q) <= n)%nat ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
