    (* [comment removed for export] *)
    Lemma frl0_fin : forall msF mo mc (r : rv) Fx (j8 : list byte) (mw : word) (q bc : Z) (j6 : list byte) (slv : word),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x1041d8) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      nframe mc spw j8 mw (Z_to_bv 64 bc) (Z_to_bv 64 0) (b8 0) (b8 1) j6 slv s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q ->
      p + 2 <= q < e -> p - q <= bc <= 0 ->
      as_SR H POST (mkCfg msF mo).
Proof.
