    (* [comment removed for export] *)
    Lemma aft2_fin : forall msF mo mc (r : rv) Fx (j8 : list byte) (mw mw2 : word) (q k2 : Z) (j6 : list byte) (slv : word),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x104488) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      nframe mc spw j8 mw (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 1) j6 slv s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra1 r = Z_to_bv 64 (q + 1) -> ra3 r = Z_to_bv 64 k2 -> ra4 r = mw2 ->
      p + 1 <= q -> q + 1 + k2 <= p + 20 -> p + 34 <= e -> 1 <= k2 <= 16 ->
