    (* [comment removed for export] *)
    Lemma pufl_loop_n : forall (n : nat) (i : Z) msF mo mc (r : rv) Fx (j8 : list byte) (mw acc : word) (q k2 : Z) (j6 : list byte) (slv : word),
      (Z.to_nat (k2 - i) <= n)%nat ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x10427c) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      nframe mc spw j8 mw (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 1) j6 slv s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra1 r = Z_to_bv 64 (q + 1) -> ra3 r = Z_to_bv 64 k2 -> ra2 r = Z_to_bv 64 i -> ra4 r = acc -> ra5 r = Z_to_bv 64 (k2 + - i) -> ra6 r = Z_to_bv 64 10 -> ra7 r = Z_to_bv 64 3 ->
