    Lemma bigl_loop_n : forall (n : nat) (d : Z) msF mo mc (r : rv) Fx (j8 : list byte) (mw : word) (q0 cnt rem : Z) (j6 : list byte) (slv : word),
      (Z.to_nat (e - (q0 + d)) <= n)%nat ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x103428) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      nframe mc spw j8 mw (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 1) j6 slv s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> ra1 r = Z_to_bv 64 q0 -> ra4 r = Z_to_bv 64 d -> ra0 r = Z_to_bv 64 cnt -> ra3 r = Z_to_bv 64 rem -> ra5 r = Z_to_bv 64 9 -> ra6 r = Z_to_bv 64 (-2147483649) -> ra7 r = Z_to_bv 64 1 ->
      p + 2 <= q0 -> 0 <= d -> q0 + d + 1 < e -> 1 <= cnt <= q0 + d - p - 1 -> 0 <= rem <= e - p ->
      as_SR H POST (mkCfg msF mo).
