    (* [comment removed for export] *)
    Lemma big_fin : forall msF mo mc (r : rv) Fx (j8 : list byte) (mant mw : word) (q0 q : Z) (j6 : list byte) (slv : word),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x1033f8) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      nframe mc spw j8 mant (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 1) j6 slv s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 q -> ra0 r = Z_to_bv 64 q -> ra1 r = Z_to_bv 64 q0 -> ra2 r = mw -> ra3 r = Z_to_bv 64 (q + - e) -> ra4 r = Z_to_bv 64 (q0 + - q) ->
      p + 2 <= q0 -> q0 <= q < e ->
