    (* [comment removed for export] *)
    Lemma puil_loop_n : forall (n : nat) (i : Z) msF mo mc (r : rv) Fx (j8 : list byte) (mant acc : word) (k : Z) (j6 : list byte) (slv : word),
      (Z.to_nat (k - i) <= n)%nat ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x103fdc) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      nframe mc spw j8 mant (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 1) j6 slv s5 s4 s3 s2 s1 s0 ra ->
      bregs r -> rs1 r = Z_to_bv 64 (p + 1) -> ra2 r = Z_to_bv 64 k -> ra1 r = Z_to_bv 64 i -> ra3 r = acc -> ra4 r = Z_to_bv 64 (k + - i) -> ra5 r = Z_to_bv 64 10 -> ra6 r = Z_to_bv 64 3 ->
      p + 34 <= e -> 0 <= i -> i + 4 <= k -> k <= 16 ->
      as_SR H POST (mkCfg msF mo).
